from boltons.cacheutils import LRU
import boltons.cacheutils as cu
c = LRU(); c['a']='A'

orig = cu.LRI.__eq__
depth = [0]
def wrapped(self, other):
    depth[0] += 1
    if depth[0] > 8:
        raise RuntimeError('TOO DEEP: ' + type(other).__name__)
    try:
        return orig(self, other)
    finally:
        depth[0] -= 1
cu.LRI.__eq__ = wrapped

depth[0]=0
try:
    print('c==list result:', c == [1,2])
except RuntimeError as e:
    print('c==list DEEP:', e)
except RecursionError:
