{"intent": "Randomized invariant check: displayed number must be < base unless the largest unit is used", "command": "cd work/repo && PYTHONPATH=src python3 - <<'PY'
import random, re
from humanize import naturalsize
import humanize.filesize as fs

random.seed(0)
sufs = {"decimal": (fs.suffixes["decimal"],1000,{}),
        "binary": (fs.suffixes["binary"],1024,{"binary":True}),
        "gnu": (fs.suffixes["gnu"],1024,{"gnu":True})}
bad = []
for mode,(suf,base,kw) in sufs.items():
    for fmt in ["%.1f","%.2f","%.0f","%.3f","%d","%.4g"]:
        for _ in range(4000):
            k = random.randint(0, 11)
            v = random.uniform(1, 2) * base**k
            if random.random() < 0.5:
                # bias to boundary
                v = base**k - random.uniform(0, base**k * 0.001)
            if random.random() < 0.3:
                v = -v
            if v == 0: continue
            out = naturalsize(v, format=fmt, **kw)
            m = re.match(r'^([-+]?[0-9.e+]+)([A-Za-z]+)?$', out.replace(' ',''))
            if not m:
                bad.append(("parse", mode, fmt, v, out)); continue
            num = float(m.group(1))
            unit = m.group(2) or ""
            # find unit index
            idx = None
            for i,s in enumerate(suf):
                if out.endswith(s): idx = i; break
            if idx is None:
                bad.append(("unit", mode, fmt, v, out)); continue
            if abs(num) >= base and idx != len(suf)-1:
                bad.append(("boundary", mode, fmt, v, out))
            # consistency: displayed num should approx equal v/base^(idx+1) rounded
            expect = v / base**(idx+1)
            disp = float(fmt % expect) if True else None
            if abs(disp - num) > max(10**-6, abs(disp)*1e-9) :
                bad.append(("value", mode, fmt, v, out, disp))
print("bad count:", len(bad))
for b in bad[:25]: print(b)
PY"}

{"command": "cd work/repo && PYTHONPATH=src python3 - <<'PY'
import random, re
from humanize import naturalsize
import humanize.filesize as fs

random.seed(1)
sufs = {"decimal": (fs.suffixes["decimal"],1000,{}),
        "binary": (fs.suffixes["binary"],1024,{"binary":True}),
        "gnu": (fs.suffixes["gnu"],1024,{"gnu":True})}
bad = []
for mode,(suf,base,kw) in sufs.items():
    for fmt in ["%.1f","%.2f","%.0f","%.3f","%d","%.4g","%e"]:
        for _ in range(5000):
            k = random.randint(1, 11)   # abs(v) >= base guaranteed mostly
            v = random.uniform(1, 2) * base**k
            if random.random() < 0.5:
                v = base**k - abs(random.uniform(0, base**k * 0.001))  # just below boundary
            if random.random() < 0.3:
                v = -v
            if abs(v) < base: continue
            out = naturalsize(v, format=fmt, **kw)
            # find which suffix the output ends with
            idx = None
            for i,s in sorted(enumerate(suf), key=lambda t:-len(t[1])):
                if out.endswith(s): idx = i; break
            if idx is None:
                bad.append(("unit", mode, fmt, v, out)); continue
            numstr = out[:-len(suf[idx])].strip()
            try:
                num = float(numstr)
            except ValueError:
                bad.append(("parse", mode, fmt, v, out)); continue
            if abs(num) >= base and idx != len(suf)-1:
                bad.append(("boundary", mode, fmt, v, out))
            # value consistency
            try:
                disp = float(fmt % (v / base**(idx+1)))
            except (ValueError, TypeError):
                continue
            if abs(disp - num) > max(1e-9, abs(disp)*1e-6):
                bad.append(("value", mode, fmt, v, out, "expected~", disp))
print("bad count:", len(bad))
from collections import Counter
print(Counter(b[0] for b in bad))
for b in bad[:30]: print(b)
PY", "intent": "Refined randomized invariant check on unit-carry behaviour"}

