const parse = require('../repo/functions/parse.js')
const cur = require('../repo/functions/diff.js')

const bump = (v, kind) => {
  const p = parse(v.version, null, true)
  switch (kind) {
    case 'major': p.major++; p.minor = 0; p.patch = 0; p.prerelease = []; break
    case 'minor': p.minor++; p.patch = 0; p.prerelease = []; break
    case 'patch': p.patch++; p.prerelease = []; break
    case 'premajor': p.major++; p.minor = 0; p.patch = 0; p.prerelease = ['0']; break
    case 'preminor': p.minor++; p.patch = 0; p.prerelease = ['0']; break
    case 'prepatch': p.patch++; p.prerelease = ['0']; break
  }
  return p
}
const norm = v => `${v.major}.${v.minor}.${v.patch}+${(v.prerelease || []).join('.')}`
function oracle (lo, hi) {
  if (norm(lo) === norm(hi)) return null
  const q = [[lo, []]]
  const seen = new Set([norm(lo)])
  while (q.length) {
    const [v, path] = q.shift()
    for (const k of ['patch', 'minor', 'major', 'prepatch', 'preminor', 'premajor']) {
      const after = bump(v, k)
      const nk = path.length ? path[0] : k
      if (after.compare(hi) === 0) return nk
      const key = norm(after)
      if (seen.has(key)) continue
      seen.add(key)
      q.push([after, path.length ? path : [k]])
    }
  }
  return '?'
}

