    // so fall through and let the comparison below report that difference.
    // e.g. 3.4.6-2 -> 3.5.2 differs in the minor, so it is a minor bump, even
    // though the higher version has a non-zero patch.
  }

  // add the `pre` prefix if we are going to a prerelease version
  const prefix = highHasPre ? 'pre' : ''

  if (v1.major !== v2.major) {
    return prefix + 'major'
  }

  if (v1.minor !== v2.minor) {
    return prefix + 'minor'
  }

  if (v1.patch !== v2.patch) {
    return prefix + 'patch'
  }

  // high and low are preleases
  return 'prerelease'
}

