{"intent": "Test boundary semantics: identifiers ending in digits, followed by various terminators", "command": "cd work/repo && node -e "
const coerce = require('./functions/coerce')
const { safeRe, t } = require('./internal/re')
const re = safeRe[t.COERCEFULL]
// Test cases where prerelease's last char is a digit and see if it survives
const inputs = [
  // identifier ends in digit then a letter follows immediately (boundary is letter => [^\d] true, boundary check passes at full extent)
  '1.2.3-abc123def',       // last char 'f' letter
  '1.2.3-abc123',          // last char '3' digit, end-of-string => $ true
  '1.2.3-abc123x456',      // ends 6 then boundary
  '1.2.3-nightly.4821',    // ends digit, end => ok
  '1.2.3-nightly.4821x',   // ends digit then letter
  '1.2.3-nightly.4821.9e1d', // ends 'd'
  '1.2.3-a1b2c3d4e5',
  // prerelease at very end - boundary $ 
  '2.3.1-nightly.7f3c',
  // What about identifier where greedy match ends exactly at a digit boundary that's NOT the full identifier?
  // e.g. all-digit subsegment followed by letter: 1.2.3-1234abc -- greedy [a-zA-Z0-9][a-zA-Z0-9-]* matches 1234abc fully (letter allowed), good
  '1.2.3-1234abc',
  // hyphen in middle
  '1.2.3-abc-def-ghi',
  // what about identifier starting with digit then containing dot then digit-leading next segment
  '1.2.3-1a.2b.3c',
  '1.2.3-12.34',
  '1.2.3-12.34x',
  // leading-zero identifier (invalid semver but let's see)
  '1.2.3-01.02',
  // identifier with only hyphen start (valid? no, but check)
  '1.2.3--',
]
for (const i of inputs) {
  const m = i.match(re)
  console.log(JSON.stringify(i), '=> groups:', m?JSON.stringify(m.slice(2)):null)
}
""}

{"intent": "Compare old vs new for cases where identifier ends at digit boundary before a letter", "command": "cd work/repo && node -e "
// Reconstruct old COERCEFULL pattern (using PRERELEASE/BUILD tokens) for comparison
const { safeRe, t } = require('./internal/re')
// build old pattern manually mirroring original code
const src = {}
// We'll just re-evaluate: old = COERCEPLAIN + optional PRERELEASE + optional BUILD + (?:\$|[^\d])
// Grab COERCEPLAIN source from safeRe by reconstructing: strip from COERCEFULL
// Simpler: define old by taking COERCEFULL's prefix and replacing middle with PRERELEASE pattern
const PRERELEASE = '(?:-(?:(0|[1-9][0-9]*|(?:[0-9]+[a-zA-Z-][0-9a-zA-Z-]*|[a-zA-Z][0-9a-zA-Z-]*))(?:\\\\.(?:(0|[1-9][0-9]*|...)))*))'  // approximating
// Instead just test behavior directly using real old token if exported
const re = safeRe[t.COERCEFULL]
console.log('COERCEFULL is:', re.source)
// Test: does new pattern ever produce a DIFFERENT (worse) result than old for inputs old handled fine?
// Key scenario: prerelease ending in a digit, followed by non-digit terminator that is NOT end
// e.g. '1.2.3-abc123/xyz' boundary after '3' is '/', which is [^\d], passes
const inputs = ['1.2.3-abc123/xyz', '1.2.3-abc123 ', '1.2.3-abc123.']
for (const i of inputs){
  const m = i.match(re)
  console.log(JSON.stringify(i),'=>',m?JSON.stringify(m.slice(2)):null)
}
""}

{"intent": "Check what happens with lookahead when prerelease could backtrack to satisfy final terminator", "command": "cd work/repo && node -e "
const { safeRe, t } = require('./internal/re')
const re = safeRe[t.COERCEFULL]
// The lookahead (?=[+]\$|[^\d]) is checked at the END of the greedy prerelease match.
// If it fails there (i.e., next char is a digit), what does the engine do?
// The prerelease part [a-zA-Z0-9][a-zA-Z0-9-]* is greedy but cannot cross a '.' 
// Actually it CAN'T include '.', because segment separator is explicit \\\\. 
// Let's confirm: does the greedy match stop at a digit after the identifier even if
// the lookahead fails? Test: identifier followed by digit (no dot) e.g. 1.2.3-abc5def
// boundary after full 'abc5def' is end => \$ true
console.log('1.2.3-abc5def'.match(re).slice(2))
// what about 1.2.3-abc.5def -- after '5def' boundary is \$
console.log('1.2.3-abc.5def'.match(re).slice(2))
// what about prerelease with segment boundary exactly at digit followed by more digits?
// 1.2.3-abc1234  => boundary after full prerelease is \$, ok
console.log('1.2.3-abc1234'.match(re).slice(2))
// Critical: lookahead boundary check happens once at end of greedy match.
// If the char right after prerelease group's greedy match is a DIGIT, lookahead fails,
// then engine backtracks prerelease shorter. When does greedy match end right before a digit?
// Only when the prerelease pattern itself cannot consume that digit: happens at the '.'
// separator... no. [a-zA-Z0-9-]* consumes digits too. So greedy match of ONE segment
// never stops before a digit within a segment. It stops at '.', '+', end, or a char not in [a-zA-Z0-9-.].
// So lookahead's [^\d] branch only matters when next char is e.g. letter/space/slash but
// wait - segment match ends at '.', the code then tries (?:\\\.segment)* ... eventually
// lookahead is after ENTIRE prerelease group. If next char is '.', prerelease group
// continues consuming (dot segment). So lookahead only evaluated when next is +, end, or
// a char outside [a-zA-Z0-9.-]. That char is never a digit (digits are in class).
// So when is [^\d] ever false at lookahead position? Only if next char is a digit, but
// digits are consumed by greedy [a-zA-Z0-9-]* ... UNLESS at segment start where first char
// must be [a-zA-Z0-9] which includes digit. Hmm digits always consumable. Let's find a
// case where lookahead fails then backtracks.
// Actually: dot followed by digits: '1.2.3-abc.123' - segment after dot starts with '1' digit,
// matches. Greedy continues... so lookahead at end(\$). Fine.
// Try where lookahead position lands on a digit: impossible since class includes digit.
// So lookahead [^\d] branch seems redundant/never-false? Test empirically with weird inputs.
const weird = ['1.2.3-abc.', '1.2.3-abc..def', '1.2.3-', '1.2.3-abc+']
for (const w of weird) console.log(JSON.stringify(w),'=>',w.match(re)?JSON.stringify(w.match(re).slice(2)):null)
""}

{"intent": "Instrument the rtl loop to check termination and match selection", "command": "cd work/repo && node -e "
const { safeRe, t } = require('./internal/re')
const version = '1.2.3.4-rc.5+rev.6'
const re = safeRe[t.COERCERTLFULL]
let match = null
let next
let iter = 0
re.lastIndex = 0
while ((next = re.exec(version)) &&
    (!match || match.index + match[0].length !== version.length)
) {
  console.log('iter',iter++,'next.index',next.index,'next[0]',JSON.stringify(next[0]),'next[1]',JSON.stringify(next[1]),'next[2]',JSON.stringify(next[2]))
  if (!match || next.index + next[0].length !== match.index + match[0].length) {
    match = next
  }
  const newLast = next.index + next[1].length + next[2].length
  console.log('  -> setting lastIndex to', newLast)
  if (newLast > version.length) { console.log('  !! lastIndex exceeds length, loop will end'); break }
  re.lastIndex = newLast
}
console.log('final match:', match?JSON.stringify(match.slice(2)):null)
""}

{"intent": "Test rtl loop termination on many digit-only strings", "command": "cd work/repo && node -e "
const coerce = require('./functions/coerce')
// potential infinite loop if next[1]+next[2] never advance lastIndex
const cases = [
  ['1.2.3.4-rc.5+rev.6', {rtl:true,includePrerelease:true}],
  ['1'.repeat(20), {rtl:true,includePrerelease:true}],
  ['1.2.3'.repeat(3), {rtl:true,includePrerelease:true}],
  ['0.0.0-0.0.0.0.0.0', {rtl:true,includePrerelease:true}],
  ['111111111111111111111111111111.2', {rtl:true,includePrerelease:true}],
  ['1.2.3-9'.repeat(5), {rtl:true,includePrerelease:true}],
  ['9'.repeat(16)+'.2.3.4', {rtl:true,includePrerelease:true}],
]
for (const [i,o] of cases){
  const t0=Date.now()
  let r
  try{ r = coerce(i,o) }catch(e){ r='ERR:'+e.message }
  console.log(JSON.stringify(i.slice(0,40)), '=>', r && r.version!==undefined?r.version:r, (Date.now()-t0)+'ms')
}
