random.seed(7)
problems = []

def check_ops(seq_ops, tag):
    iset = IndexedSet()
    ref = []
    for op in seq_ops:
        kind, val = op
        try:
            if kind == 'add':
                if val not in ref:
                    iset.add(val); ref.append(val)
            elif kind == 'remove':
                iset.remove(val); ref.remove(val)
            elif kind == 'discard':
                iset.discard(val)
                if val in ref: ref.remove(val)
            elif kind == 'pop_mid':
                if ref:
                    i = random.randrange(len(ref))
                    got = iset.pop(i)
                    exp = ref.pop(i)
                    if got != exp: problems.append((tag, 'pop', i, got, exp))
            elif kind == 'pop_neg':
                if ref:
                    i = random.randrange(-len(ref), len(ref))
                    got = iset.pop(i)
                    exp = ref.pop(i)
                    if got != exp: problems.append((tag, 'popneg', i, got, exp))
        except Exception as e:
            problems.append((tag, 'op-exc', op, repr(e)))
            return
    # integer indexing invariants
    n = len(ref)
    for i in range(-n, n):
        try:
            got = iset[i]
        except IndexError as e:
            problems.append((tag, 'idx-should-work', i, repr(e))); continue
        if got != ref[i]:
            problems.append((tag, 'idx', i, got, ref[i]))
    for i in list(range(n, n+5)) + list(range(-n-5, -n)):
        try:
            got = iset[i]
            problems.append((tag, 'idx-should-raise', i, got))
        except IndexError:
            pass
        except Exception as e:
            problems.append((tag, 'idx-wrong-exc', i, repr(e)))
    # pop out of range
    for i in (n, n+3, -n-1, -n-4, 10**6, -10**6):
        t = IndexedSet(iset)
        try:
            t.pop(i)
            problems.append((tag, 'pop-should-raise', i))
        except IndexError:
            pass
        except Exception as e:
            problems.append((tag, 'pop-wrong-exc', i, repr(e)))
    # slicing: positive steps vs list; all steps vs fresh set
    fresh = IndexedSet(ref)
    bounds = [None, -n-3, -n, -3, -1, 0, 1, 2, 3, n-1, n, n+3] if n else [None, -1, 0, 1]
    for a in bounds:
        for b in bounds:
            for st in (None, 1, 2, 5, -1, -2, -7):
                sl = slice(a, b, st)
                try:
                    got = list(iset[sl])
                except Exception as e:
                    problems.append((tag, 'slice-exc', (a,b,st), repr(e))); continue
                expf = list(fresh[sl])
                if got != expf:
                    problems.append((tag, 'slice-fresh', (a,b,st), got, expf))
                if st is None or st > 0:
                    expl = ref[a:b:st]
                    if got != expl:
                        problems.append((tag, 'slice-list', (a,b,st), got, expl))
                if not isinstance(iset[sl], IndexedSet):
                    problems.append((tag, 'slice-type', (a,b,st)))

for trial in range(400):
    n = random.randint(0, 15)
    base = list(range(n))
    random.shuffle(base)
    ops = []
    live = []
    for _ in range(random.randint(1, 25)):
        r = random.random()
        if r < 0.45 or not live:
