// Independent oracle derived from README + pinned tests:
// - equal -> null
// - prerelease->release special: low core X.0.0-pre -> 'major' (pinned: 1.0.0-1->1.1.1 = major);
//   else lowest differing core component; identical cores -> lowest nonzero of core (X.0.0 -> major [again first rule], Y.0.0 -> minor, *.*.Z -> patch)
// - otherwise: lowest differing component of the two full versions, 'pre' prefix iff target (higher) has prerelease; identical cores -> 'prerelease'
function spec(a, b) {
  const va = parse(a), vb = parse(b)
  const cmp = va.compare(vb)
  if (cmp === 0) return null
  const high = cmp > 0 ? va : vb
  const low = cmp > 0 ? vb : va
  const highPre = !!high.prerelease.length
  const lowPre = !!low.prerelease.length
  if (lowPre && !highPre) {
    if (low.major === high.major && low.minor === high.minor && low.patch === high.patch) {
      // identical cores: lowest nonzero component of the core, X.0.0-pre -> release is 'major'
      if (low.patch === 0 && low.minor === 0) return 'major'  // X.0.0-1 -> X.0.0 (pinned 1.0.0-1->1.0.0 = major)
      if (high.patch !== 0) return 'patch'
      return 'minor'
    }
    if (low.patch === 0 && low.minor === 0) return 'major' // pinned quirk: 1.0.0-1 -> 1.1.1 = major
    if (low.major !== high.major) return 'major'
    if (low.minor !== high.minor) return 'minor'
    return 'patch'
  }
  const prefix = highPre ? 'pre' : ''
  if (va.major !== vb.major) return prefix + 'major'
  if (va.minor !== vb.minor) return prefix + 'minor'
  if (va.patch !== vb.patch) return prefix + 'patch'
  return 'prerelease'
}

let fails = 0, asym = 0, badType = 0, oracleFail = 0
for (const a of vers) for (const b of vers) {
  if (a === b) continue
  const got = diff(a, b)
  const rev = diff(b, a)
  if (got !== rev) { asym++; if (asym <= 10) console.log('ASYM', a, b, got, rev) }
