            "binary": ["KiB","MiB","GiB","TiB","PiB","EiB","ZiB","YiB","RiB","QiB"],
            "gnu": list("KMGTPEZYRQ")}

# Invariant: displayed number < base, OR unit is the largest one.
violations = []
