for mode_kw in ({}, {"binary": True}, {"gnu": True}):
    base = 1024 if mode_kw else 1000
    key = "gnu" if "gnu" in mode_kw else ("binary" if "binary" in mode_kw else "decimal")
    sfx = suffixes[key]
    for fmt in ("%.1f", "%.3f", "%.0f", "%d", "%g"):
        for v in vals:
