import re, math
from humanize.filesize import naturalsize, suffixes, _displayed_magnitude

num_re = re.compile(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?")

def check(value, binary=False, gnu=False, fmt="%.1f"):
    out = naturalsize(value, binary=binary, gnu=gnu, format=fmt)
    base = 1024 if (gnu or binary) else 1000
    m = num_re.search(out)
    if m is None:
        return f"no number in output: {out!r}"
    disp = abs(float(m.group()))
    # clamp region: value >= base**10 means largest unit kept, display may exceed base
    clamped = abs(value) >= base**10
    if not clamped and disp >= base:
        return f"displayed {disp} >= base: {out!r}"
    if not clamped and disp < 1:
        return f"displayed {disp} < 1: {out!r}"
    return None

