        "m":1e-3,"μ":1e-6,"n":1e-9,"p":1e-12,"f":1e-15,"a":1e-18,"z":1e-21,"y":1e-24,"r":1e-27,"q":1e-30}

def parse(s, unit):
    u = unit
    if u and s.endswith(u): s = s[:-len(u)]
    s = s.strip()
    m = re.fullmatch(r"(-?[\d.]+)\s*([kMGTPEZYRQmμnpfazyrq]?)", s)
    if not m:
        m2 = re.fullmatch(r"(-?[\d.]+) x 10([⁻⁰-⁹]+)", s)
        if m2:
            return float(m2.group(1)) * 10**int(m2.group(2).translate(SUPER)), None, True
        return None, None, None
    mant, pref = m.group(1), m.group(2)
    return float(mant), PREF[pref], False

fail = []
def check(v, u, p):
    out = metric(v, u, p)
    val, mult, sci = parse(out, u)
    if val is None:
        fail.append((v,u,p,out,"unparsed")); return
    got = val if mult is None else val*mult
    if sci:
        # scientific: check precision sig digits approx
        if abs(got - v) > 0.6*abs(v)*10**(1-p) if p>0 else abs(got-v)>0.6*abs(v):
            pass
        return
    # value correctness: relative error at most 0.5*10^(int_digits-p) style
    intd = len(str(int(abs(round(val, 10))))) if val else 1
    if v != 0:
        tol = 0.5 * 10**(intd - p) * abs(v)/abs(val if val else 1) if p>0 else 0.5*10**intd*abs(v)/abs(val)
        if abs(got - v) > tol*1.0001:
            fail.append((v,u,p,out,f"accuracy got={got} tol={tol}")); return
    # decimals rule
    dec = len(out.split(" ")[0].split(u)[0].partition(".")[2]) if "." in out.split(" ")[0] else 0
